"119 :   private boolean isPinningPropertyUse(Node n) {
120 :     // Rather than looking for cases that are uses, we assume all references are
121 :     // pinning uses unless they are:
122 :     //  - a simple assignment (x.a = 1)
123 :     //  - a compound assignment or increment (x++, x += 1) whose result is
124 :     //    otherwise unused
125 : 
126 :     Node parent = n.getParent();
127 :     if (n == parent.getFirstChild()) {
128 :       if (parent.isAssign()) {
129 :         // A simple assignment doesn't pin the property.
130 :         return false;
131 :       } else if (NodeUtil.isAssignmentOp(parent)
132 :             || parent.isInc() || parent.isDec()) {
133 :         // In general, compound assignments are both reads and writes, but
134 :         // if the property is never otherwise read we can consider it simply
135 :         // a write.
136 :         // However if the assign expression is used as part of a larger
137 :         // expression, we much consider it a read. For example:
138 :         //    x = (y.a += 1);
139 :         return NodeUtil.isExpressionResultUsed(parent);
140 :       }
141 :     }
142 :     return true;
143 :   }"

